import{_ as t,o,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.4.20 Update Workspace Member Role","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-20-update-workspace-member-role/spec.md","filePath":"feature/agency-workspace/3-4-20-update-workspace-member-role/spec.md"}'),i={name:"feature/agency-workspace/3-4-20-update-workspace-member-role/spec.md"};function s(n,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-4-20-update-workspace-member-role" tabindex="-1">3.4.20 Update Workspace Member Role <a class="header-anchor" href="#_3-4-20-update-workspace-member-role" aria-label="Permalink to &quot;3.4.20 Update Workspace Member Role&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.20</td></tr><tr><td>Feature</td><td>Update Workspace Member Role</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>MANAGER</td></tr><tr><td>Version</td><td>3.2 — 2026-09-25 — corrected duplicate-MANAGER guard citation from mis-cited BR-05 to BR-87</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when the MANAGER of a Workspace changes the role of one of its members.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose:</strong> Lets the MANAGER adjust a member&#39;s role to match the work actually being done, including handing over the MANAGER role.</li><li><strong>Interface:</strong> A role selector in the member table at <code>/workspaces/:id/members</code>, offering MANAGER, CREATOR, and CLIENT.</li><li><strong>Data Processing:</strong> The system loads the member, applies the single-MANAGER guards, updates the role, and returns the updated member.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Update Member Role Screen:</p><ul><li>The member table on <code>/workspaces/:id/members</code>.</li><li>A role selector per member with the values MANAGER, CREATOR, CLIENT.</li><li>A blocked state with a clear message when the change would leave the Workspace without a MANAGER or would create a second one.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Workspace identifier; the member identifier; the new role.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> The caller&#39;s role in the Workspace; the member record and its current role; the count of active MANAGERs in the Workspace; the member&#39;s user record for building the response.</li><li><strong>Output:</strong> The updated member — id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive, carrying the new role.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-35:</strong> <code>@RequireRoleAspect</code> re-reads the caller&#39;s role from the DB at request time; <code>SystemRole.ADMIN</code> bypasses the check. Only MANAGER may change roles; any other caller → 403 <code>FORBIDDEN</code>. This role check runs before any service-level guard.</li><li><strong>BR-33:</strong> There is an <code>updateMemberRole</code> endpoint (<code>PATCH /{workspaceId}/members/{memberId}/role</code>) in this codebase for changing an existing member&#39;s role without reusing the invite flow — implemented here, not TBD. A role change affects the current Workspace only — it does not carry over to the same member&#39;s roles in other Workspaces of the Agency.</li><li><strong>BR-83:</strong> Last-MANAGER guard on demotion — mirroring BR-28, if the member is the only active MANAGER of the Workspace and the new role is not MANAGER, the request is blocked with 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>; another MANAGER must be in place first. This guard is checked before the duplicate-MANAGER guard.</li><li><strong>BR-87:</strong> Duplicate-MANAGER guard on promotion (checked second) — if the new role is MANAGER and the member is not currently a MANAGER, the request is blocked with 409 <code>MANAGER_ALREADY_ASSIGNED</code> when the Workspace already has another active MANAGER, since a Workspace has exactly one active MANAGER at a time. Previously mis-cited as BR-05 (BR-05 is the unrelated login anti-enumeration rule); corrected here.</li><li><strong>BR-29:</strong> Multi-tenancy — the member lookup is scoped to the Workspace; a member that does not exist, is not active, or belongs to another Workspace → 404 <code>NOT_FOUND</code>.</li><li><strong>BR-31:</strong> Four workspace roles: OWNER, MANAGER, CREATOR, CLIENT (<code>MemberRole</code> enum); OWNER is not assignable at Workspace level here, since these role values are MANAGER, CREATOR, CLIENT.</li><li><strong>BR-82:</strong> <code>role</code> must be one of the enum values; any other value is rejected.</li><li>There is no exception for changing one&#39;s own role — a MANAGER acting on themselves is subject to the same guards as any other member.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Caller must be the MANAGER of that Workspace; otherwise 403 <code>FORBIDDEN</code> (BR-35). Toast MSG39.</li><li>role empty → Display: MSG02.</li><li>The member must exist, be active, and belong to that Workspace (BR-29); otherwise 404 <code>NOT_FOUND</code>. Toast MSG38.</li><li>The new role must be one of MANAGER, CREATOR, CLIENT (BR-31, BR-82); otherwise Display: MSG95.</li><li>Demoting the only active MANAGER (BR-83) → 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>. Toast MSG96.</li><li>Promoting to MANAGER while another active MANAGER exists (duplicate-MANAGER guard, no BR-xx code — see BA conflict note above) → 409 <code>MANAGER_ALREADY_ASSIGNED</code>. Display: MSG95.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>MANAGER opens <code>/workspaces/:id/members</code> and picks a new role for a member in the role selector.</li><li>System confirms the caller holds the MANAGER role in that Workspace (BR-35); otherwise the request fails with 403 <code>FORBIDDEN</code>.</li><li>System loads the member and checks that it exists, is active, and belongs to that Workspace (BR-29); otherwise the request fails with 404 <code>NOT_FOUND</code>.</li><li>System applies the guards in order: the last-MANAGER guard when the member is the only active MANAGER and is being demoted (BR-83), then the duplicate-MANAGER guard when promoting to MANAGER while another active MANAGER exists (no BR-xx code assigned — see BA conflict note).</li><li>System stores the new role on the membership and returns the updated member. No dedicated success-toast MSG code exists in the global table for this action (closest is none — gap noted in report; screen simply refreshes silently or reuses a generic confirmation).</li><li>Screen refreshes the role shown for that member.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: Caller is not the MANAGER of that Workspace (BR-35) → 403 <code>FORBIDDEN</code>, toast MSG39. 2.a2: The screen blocks the action; the caller cannot change roles without the MANAGER role.</li><li>3.a1: Member does not exist, is not active, or belongs to another Workspace (BR-29) → 404 <code>NOT_FOUND</code>, toast MSG38. 3.a2: The screen refreshes the member list, since the target row no longer applies.</li><li>4.a1: Demoting the only active MANAGER to CREATOR or CLIENT (BR-83) → 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code>, toast MSG96. 4.a2: The MANAGER hands the MANAGER role to another member first, then retries the demotion.</li><li>4.b1: Promoting a member to MANAGER while the Workspace already has an active MANAGER (duplicate-MANAGER guard, no BR-xx code) → 409 <code>MANAGER_ALREADY_ASSIGNED</code>, Display: MSG95 (generic role-rejection message; no dedicated MSG code exists for this conflict). 4.b2: The MANAGER demotes the current MANAGER first, or picks a different role.</li><li>A MANAGER demotes themselves → allowed when at least one other MANAGER remains in the Workspace; blocked with 409 <code>LAST_MANAGER_CANNOT_BE_REMOVED</code> when they are the only MANAGER, with no exception for self-changes.</li><li>A role change between CREATOR and CLIENT → always allowed, since neither guard triggers unless the old or new role is MANAGER.</li><li>Setting the role to the value it already holds → allowed; no guard blocks a no-op change.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The member holds the new role in this Workspace only.</li><li>The Workspace still has exactly one active MANAGER.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>None.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const A=t(i,[["render",s]]);export{u as __pageData,A as default};
